variables {F F' E L' : Type} [Field F] [Field F'] [Field E] [Field L']
  [Algebra F E] [Algebra F' L']

def Emb_theta (θ : F ≃+* F') (E L' : Type) [Field E] [Field L'] [Algebra F E] [Algebra F' L'] :=
  { φ : E →+* L' // Function.Injective φ ∧ φ.comp (algebraMap F E) = (algebraMap F' L').comp θ.toRingHom }

def Iso_theta (θ : F ≃+* F') (E L' : Type) [Field E] [Field L'] [Algebra F E] [Algebra F' L'] :=
  { e : E ≃+* L' // e.toRingHom.comp (algebraMap F E) = (algebraMap F' L').comp θ.toRingHom }

def Emb_F (E L' : Type) [Field E] [Field L'] [Algebra F E] [Algebra F L'] :=
  Emb_theta (F:=F) (F':=F) (E:=E) (L':=L') (θ := RingEquiv.refl F)

end Output

